"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../../components/ui/Button";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminMarketing() {
    const [campaigns] = useState([
        { id: 1, name: "Promoção de Verão", channel: "WhatsApp", reached: 1200, converted: 85, status: "ATIVA" },
        { id: 2, name: "Reativação de Clientes", channel: "SMS", reached: 450, converted: 12, status: "CONCLUÍDA" },
        { id: 3, name: "Novo Corte Degradê", channel: "Instagram", reached: 5400, converted: 120, status: "ATIVA" },
    ]);

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <header className="mb-10 lg:mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div>
                    <h1 className="text-3xl font-semibold mb-1">
                        Centro de <span className="text-[#D4AF37]">Marketing</span>
                    </h1>
                    <p className="text-gray-400 text-sm">Campanhas de fidelização e captação de clientes</p>
                </div>
                <div className="flex gap-4">
                    <Button variant="outline" className="gap-2">
                        <Icon name="MessageSquare" className="w-4 h-4" /> Automação
                    </Button>
                    <Button className="gap-2">
                        <Icon name="Plus" className="w-4 h-4" /> Nova Campanha
                    </Button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-12">
                {[
                    { title: "Alcance Total", value: "7.050", icon: "Users", sub: "Pessoas impactadas" },
                    { title: "Conversão", value: "3.2%", icon: "Target", sub: "Cliques em agendamento" },
                    { title: "ROI Estimado", value: "4.5x", icon: "TrendingUp", sub: "Retorno sobre investimento" },
                ].map((stat, i) => (
                    <div key={i} className="bg-[#111111] border border-[#1f1f1f] p-8 rounded-3xl relative overflow-hidden group">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-[#D4AF37]/5 rounded-bl-full group-hover:bg-[#D4AF37]/10 transition-all pointer-events-none" />
                        <Icon name={stat.icon} className="w-8 h-8 text-[#D4AF37] mb-6" />
                        <p className="text-gray-500 text-[10px] uppercase font-bold tracking-widest mb-1">{stat.title}</p>
                        <h3 className="text-3xl font-bold mb-2 tracking-tight">{stat.value}</h3>
                        <p className="text-[10px] text-gray-400 uppercase tracking-tighter">{stat.sub}</p>
                    </div>
                ))}
            </div>

            <h3 className="text-lg font-bold mb-6 tracking-tight">Campanhas Ativas</h3>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {campaigns.map((camp) => (
                    <div key={camp.id} className="bg-[#111111] border border-[#1f1f1f] p-6 rounded-2xl flex items-center justify-between group hover:border-[#D4AF37]/30 transition-all">
                        <div className="flex items-center gap-6">
                            <div className="w-14 h-14 rounded-2xl bg-[#0a0a0a] flex items-center justify-center text-[#D4AF37] border border-[#1f1f1f] group-hover:scale-110 transition-transform">
                                <Icon name={camp.channel === 'WhatsApp' ? 'MessageCircle' : camp.channel === 'SMS' ? 'Smartphone' : 'Instagram'} className="w-6 h-6" />
                            </div>
                            <div>
                                <h4 className="font-bold text-base mb-1">{camp.name}</h4>
                                <div className="flex gap-4 text-[10px] text-gray-500 uppercase font-bold">
                                    <span>{camp.reached} Alcance</span>
                                    <span className="text-emerald-500">{camp.converted} Conversões</span>
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className={`text-[9px] font-black px-3 py-1 rounded-full ${camp.status === 'ATIVA' ? 'bg-[#0f2419] text-[#4ade80]' : 'bg-gray-800 text-gray-400'}`}>
                                {camp.status}
                            </span>
                            <button className="block mt-4 text-[#D4AF37] text-[10px] font-bold uppercase hover:underline">Ver Detalhes</button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
